'use client';

import { useEffect, useRef, useState } from 'react';
import { Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';

// Plate artwork generated by scripts/gen-nameplate.mjs and post-processed by
// scripts/key-backdrop.mjs. The ratios below are *measured from the files*,
// not guessed — they say how much of the art is the writable inner panel, and
// getting them wrong pushes the text off the plate.
const PLATES = {
  royal: { url: '/ui/nameplate.png', aspect: 930 / 331, panelW: 0.904, panelH: 0.74 },
  neon: { url: '/ui/nameplate-neon.png', aspect: 766 / 314, panelW: 0.795, panelH: 0.643 },
  chrome: { url: '/ui/nameplate-chrome.png', aspect: 656 / 276, panelW: 0.916, panelH: 0.906 },
} as const;

/**
 * Swap this to change the plate used by every featured character.
 * `neon` is currently unusable — the model keeps rendering its inner panel as
 * background rather than solid glass, so the keyed result has a hole.
 */
const PLATE = PLATES.chrome;

let plaqueTexture: THREE.Texture | null = null;
let plaquePending = false;

// Remote avatars are shared across every label showing the same person
const avatarCache = new Map<string, THREE.Texture | null>();

function useAvatarTexture(url?: string) {
  const [, bump] = useState(0);

  useEffect(() => {
    if (!url || avatarCache.has(url)) return;
    // Reserve the slot so two labels don't both start a download
    avatarCache.set(url, null);

    let cancelled = false;
    const loader = new THREE.TextureLoader();
    loader.setCrossOrigin('anonymous');
    loader.load(
      url,
      (tex) => {
        tex.colorSpace = THREE.SRGBColorSpace;
        avatarCache.set(url, tex);
        if (!cancelled) bump((v) => v + 1);
      },
      undefined,
      // A blocked CDN shouldn't break the label — just show no picture
      () => avatarCache.set(url, null),
    );

    return () => {
      cancelled = true;
    };
  }, [url]);

  return url ? avatarCache.get(url) ?? null : null;
}

function usePlaqueTexture(enabled: boolean) {
  const [, bump] = useState(0);

  useEffect(() => {
    if (!enabled || plaqueTexture || plaquePending) return;
    plaquePending = true;

    let cancelled = false;
    new THREE.TextureLoader().load(PLATE.url, (tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 8;
      plaqueTexture = tex;
      plaquePending = false;
      if (!cancelled) bump((v) => v + 1);
    });

    return () => {
      cancelled = true;
    };
  }, [enabled]);

  return enabled ? plaqueTexture : null;
}

/**
 * Floating name label.
 *
 * `fancy` swaps the plain dimmed plate for the ornate plaque artwork used by
 * featured characters. Either way the backing is sized from troika's measured
 * text bounds in `onSync` and applied through refs, so a long nickname never
 * costs a re-render just to resize a quad.
 */
export default function NameTag({
  text,
  position,
  fontSize = 0.14,
  color = '#ffffff',
  fancy = false,
  avatarUrl,
  likes = 0,
}: {
  /** TikTok likes from this person, shown as "name - ♥ xN" when above zero */
  likes?: number;
  text: string;
  position: [number, number, number];
  fontSize?: number;
  color?: string;
  fancy?: boolean;
  /** Remote avatar (e.g. a TikTok profile picture) shown left of the plate */
  avatarUrl?: string;
}) {
  const plate = useRef<THREE.Mesh>(null);
  const plaque = useRef<THREE.Mesh>(null);
  // troika measures the text long before the plaque texture finishes loading,
  // so the size has to be remembered and re-applied when the mesh finally
  // mounts — otherwise it stays at its initial zero scale and never appears.
  const measured = useRef<{ w: number; h: number } | null>(null);
  const texture = usePlaqueTexture(fancy);
  const avatar = useAvatarTexture(avatarUrl);
  const avatarRef = useRef<THREE.Mesh>(null);
  const avatarSize = fontSize * 1.9;

  const prefix = `${text} - `;
  const label = likes > 0 ? `${prefix}♥ x${likes}` : text;
  // Only the heart is red; the count goes back to the label colour
  const colorRanges =
    likes > 0 ? { 0: color, [prefix.length]: '#ff2d55', [prefix.length + 1]: color } : undefined;

  const applyMeasured = (mesh: THREE.Mesh | null) => {
    if (mesh && measured.current) {
      mesh.scale.set(measured.current.w, measured.current.h, 1);
    }
    // Park the avatar just outside the left edge of the plate
    if (avatarRef.current && measured.current) {
      avatarRef.current.position.x = -(measured.current.w / 2 + avatarSize * 0.62);
    }
  };

  return (
    <Billboard position={position}>
      {fancy && texture && (
        <mesh
          ref={(m) => {
            plaque.current = m;
            applyMeasured(m);
          }}
          position={[0, 0, -0.03]}
          scale={[0, 0, 1]}
        >
          <planeGeometry args={[1, 1]} />
          <meshBasicMaterial map={texture} transparent alphaTest={0.05} toneMapped={false} />
        </mesh>
      )}

      {!fancy && (
        <mesh
          ref={(m) => {
            plate.current = m;
            applyMeasured(m);
          }}
          position={[0, 0, -0.02]}
          scale={[0, 0, 1]}
        >
          <planeGeometry args={[1, 1]} />
          <meshBasicMaterial
            color={'#000000'}
            transparent
            opacity={0.55}
            depthWrite={false}
            toneMapped={false}
          />
        </mesh>
      )}

      {avatar && (
        <mesh
          ref={(m) => {
            avatarRef.current = m;
            applyMeasured(null);
          }}
          position={[0, 0, -0.01]}
        >
          <circleGeometry args={[avatarSize / 2, 24]} />
          <meshBasicMaterial map={avatar} toneMapped={false} />
        </mesh>
      )}

      <Text
        fontSize={fontSize}
        color={color}
        anchorX="center"
        anchorY="middle"
        outlineWidth={fancy ? 0.01 : 0.006}
        outlineColor="#000000"
        // troika supports colorRanges; drei forwards it but leaves it untyped
        {...({ colorRanges } as object)}
        onSync={(troika) => {
          const bounds = (
            troika as unknown as { textRenderInfo?: { blockBounds?: number[] } }
          ).textRenderInfo?.blockBounds;
          if (!bounds) return;

          // blockBounds is [minX, minY, maxX, maxY] in local text units
          const tw = bounds[2] - bounds[0];
          const th = bounds[3] - bounds[1];

          if (fancy) {
            // Grow the plaque until its engraved panel clears the text on both
            // axes — a long name needs width, a tall glyph needs height.
            const byWidth = (tw + fontSize * 0.8) / PLATE.panelW;
            const byHeight = ((th + fontSize * 0.7) / PLATE.panelH) * PLATE.aspect;
            const w = Math.max(byWidth, byHeight);
            measured.current = { w, h: w / PLATE.aspect };
            applyMeasured(plaque.current);
          } else {
            measured.current = {
              w: tw + fontSize * 0.9,
              h: th + fontSize * 0.55,
            };
            applyMeasured(plate.current);
          }
        }}
      >
        {label}
      </Text>
    </Billboard>
  );
}
